router3.get("/kommo/status", async (_req, res) => {
  const subdomain = getKommoSubdomain();
  const accessToken = getKommoAccessToken();
  if (!isKommoConfigured()) {
    res.status(503).json({
      ok: false,
      kommo_configured: false,
      kommo_subdomain: subdomain || null,
      error: "Faltan KOMMO_SUBDOMAIN y/o KOMMO_ACCESS_TOKEN (o alias KOMMO_TOKEN_LARGA_DURACION / SUBDOMINIO_KOMMO)"
    });
    return;
  }
  const headers = { Authorization: `Bearer ${accessToken}` };
  try {
    const r5 = await fetch(`https://${subdomain}.kommo.com/api/v4/account`, { headers });
    const text2 = await r5.text();
    let account = null;
    try {
      account = JSON.parse(text2);
    } catch {
      account = null;
    }
    if (!r5.ok) {
      res.status(502).json({
        ok: false,
        kommo_configured: true,
        kommo_subdomain: subdomain,
        kommo_api: "error",
        http_status: r5.status,
        hint: r5.status === 401 ? "Token inv\xE1lido o expirado \u2014 revisa KOMMO_TOKEN_LARGA_DURACION" : "Revisa subdominio y permisos del token"
      });
      return;
    }
    const [sourcesRes, talksRes, widgetsRes] = await Promise.all([
      fetch(`https://${subdomain}.kommo.com/api/v4/sources`, { headers }),
      fetch(`https://${subdomain}.kommo.com/api/v4/talks?limit=50`, { headers }),
      fetch(`https://${subdomain}.kommo.com/api/v4/widgets`, { headers })
    ]);
    const safeJson = async (resp) => {
      const raw = await resp.text().catch(() => "");
      if (!resp.ok) return { data: null, error: `HTTP ${resp.status}: ${raw.slice(0, 120)}` };
      if (!raw.trim()) return { data: null, error: null };
      try {
        return { data: JSON.parse(raw), error: null };
      } catch (e4) {
        return {
          data: null,
          error: `JSON inv\xE1lido (${resp.status}): ${e4 instanceof Error ? e4.message : String(e4)}`
        };
      }
    };
    let sources = [];
    const sourcesParsed = await safeJson(sourcesRes);
    const sourcesError = sourcesParsed.error;
    if (sourcesParsed.data) {
      sources = sourcesParsed.data._embedded?.sources ?? [];
    }
    const originCounts = {};
    const talksParsed = await safeJson(talksRes);
    const talksError = talksParsed.error;
    if (talksParsed.data) {
      for (const t4 of talksParsed.data._embedded?.talks ?? []) {
        const origin2 = (t4.origin || "unknown").toLowerCase();
        originCounts[origin2] = (originCounts[origin2] ?? 0) + 1;
      }
    }
    const sourceSummaries = sources.map((s7) => ({
      id: s7.id ?? null,
      name: s7.name ?? null,
      origin_code: s7.origin_code ?? null,
      external_id: s7.external_id ?? null,
      default: s7.default ?? null
    }));
    const widgetsParsed = await safeJson(widgetsRes);
    const widgets = (widgetsParsed.data?._embedded?.widgets ?? []).map((w5) => ({
      code: w5.code ?? null,
      name: w5.name ?? null,
      active: Boolean(w5.active ?? w5.is_active)
    }));
    const blob = [
      JSON.stringify(sourceSummaries),
      JSON.stringify(widgets),
      Object.keys(originCounts).join(" ")
    ].join(" ").toLowerCase();
    const hasFacebook = /facebook|messenger|\bfb[_-]/.test(blob);
    const hasInstagram = /instagram|\big[_-]/.test(blob);
    const hasWhatsapp = /whats?app|waba/.test(blob);
    res.json({
      ok: true,
      kommo_configured: true,
      kommo_subdomain: subdomain,
      kommo_api: "connected",
      account_name: account?.name ?? null,
      channels: {
        facebook: hasFacebook,
        instagram: hasInstagram,
        whatsapp: hasWhatsapp
      },
      sources: sourceSummaries,
      sources_error: sourcesError,
      widgets: widgets.filter(
        (w5) => /facebook|instagram|messenger|whats?app|waba|meta/i.test(
          `${w5.code ?? ""} ${w5.name ?? ""}`
        )
      ),
      widgets_error: widgetsParsed.error,
      recent_talk_origins: originCounts,
      talks_error: talksError
    });
  } catch (err2) {
    res.status(502).json({
      ok: false,
      kommo_configured: true,
      kommo_subdomain: subdomain,
      kommo_api: "unreachable",
      error: err2 instanceof Error ? err2.message : String(err2)
    });
  }
});
